Instead of sequence-aware alignment, this simply concatenates the per-step
tensors of each side along the token dimension (in ascending step order) and
truncates both sides to the shorter total length.
"""

from __future__ import annotations

from typing import Dict

import torch

from sglang.srt.debug_utils.comparator.dims import SEQ_DIM_NAME, TOKEN_DIM_NAME
from sglang.srt.debug_utils.comparator.utils import Pair

_UNNAMED_TOKEN_DIM_FALLBACK: int = 0


def execute_token_aligner_concat_steps(
    tensor_of_step_pair: Pair[Dict[int, torch.Tensor]],
) -> Pair[torch.Tensor]:
    """Concatenate per-step tensors of both sides, then truncate to the shorter side.

    Steps are concatenated in ascending step-key order. The token dimension is
    detected from named dims ('t' first, then 's', else dim 0). After
    concatenation, both sides are trimmed along the token dimension to the
    minimum of the two total lengths.
    """
    concatenated: Pair[torch.Tensor] = tensor_of_step_pair.map(_concat_steps)

    token_dim_x: int = _detect_token_dim(concatenated.x)
    token_dim_y: int = _detect_token_dim(concatenated.y)

    min_len: int = min(
        concatenated.x.size(token_dim_x), concatenated.y.size(token_dim_y)
    )

    return Pair(
        x=concatenated.x.narrow(token_dim_x, 0, min_len),
        y=concatenated.y.narrow(token_dim_y, 0, min_len),
    )


def _concat_steps(tensor_of_step: Dict[int, torch.Tensor]) -> torch.Tensor:
    tensors: list[torch.Tensor] = [
        tensor_of_step[step] for step in sorted(tensor_of_step.keys())
    ]
    token_dim: int = _detect_token_dim(tensors[0])
    if len(tensors) == 1:
        return tensors[0]
    return torch.cat(tensors, dim=token_dim)


def _detect_token_dim(tensor: torch.Tensor) -> int:
    """Detect the token dim: 't' takes priority, then 's', else dim 0."""
    names: tuple = tensor.names
    if any(name is not None for name in names):
        if TOKEN_DIM_NAME in names:
            return list(names).index(TOKEN_DIM_NAME)
        if SEQ_DIM_NAME in names:
            return list(names).index(SEQ_DIM_NAME)
    return _UNNAMED_TOKEN_DIM_FALLBACK
