_SGLANG_SEQ_LENS_NAME: str = "seq_lens"
_MEGATRON_CU_SEQLENS_NAME: str = "cu_seqlens_q"


def load_thd_seq_lens_only(
    dump_path: Path, df: pl.DataFrame
) -> Optional[dict[int, list[int]]]:
    """Load per-step sequence lengths without running the full alignment pipeline.

    Returns a dict mapping step index to per-sequence lengths, or None if:
      - no recognized framework plugin is detected,
      - the detected plugin reports no CP-sharded names (empty frozenset), or
      - neither a ``seq_lens`` (SGLang) nor a ``cu_seqlens_q`` (Megatron) tensor
        is present in the dump.
    """
    plugin: Optional[_AuxFrameworkPlugin] = _detect_plugin(df, dump_path=dump_path)
    if plugin is None:
        return None

    if not plugin.cp_sharded_names:
        return None

    available_names: set[str] = set(df["name"].unique().to_list())

    if _SGLANG_SEQ_LENS_NAME in available_names:
        source_name: str = _SGLANG_SEQ_LENS_NAME
    elif _MEGATRON_CU_SEQLENS_NAME in available_names:
        source_name = _MEGATRON_CU_SEQLENS_NAME
    else:
        return None

    steps: list[int] = sorted(df["step"].unique().to_list())

    result: dict[int, list[int]] = {}
    for step in steps:
        tensor: Optional[torch.Tensor] = _load_tensor(
            name=source_name, step=step, df=df, dump_path=dump_path
        )
        if tensor is None:
            continue

        if source_name == _SGLANG_SEQ_LENS_NAME:
            result[step] = [int(v) for v in tensor.tolist()]
        else:
            # cu_seqlens_q is cumulative; consecutive differences give per-seq lengths.
            result[step] = [int(v) for v in (tensor[1:] - tensor[:-1]).tolist()]

    return result


def _load_tensor(
    *, name: str, step: int, df: pl.DataFrame, dump_path: Path
) -> Optional[torch.Tensor]:
    rows = filter_rows(df, conditions={"name": name, "step": step})
    if not rows:
        return None

    loaded: list[ValueWithMeta] = [
        ValueWithMeta.load(dump_path / r["filename"]) for r in rows
    ]
    loaded = filter_to_non_empty_dp_rank(loaded)

    tensors: list[torch.Tensor] = [
        item.value for item in loaded if isinstance(item.value, torch.Tensor)
    ]
    if not tensors:
        return None

    return tensors[0]
